-- Self-healing: a run still 'running' after 2 hours crashed before "Finish run".
UPDATE jobs.runs SET status = 'failed', finished_at = now()
 WHERE status = 'running' AND started_at < now() - interval '2 hours';
INSERT INTO jobs.runs (trigger) VALUES ($1) RETURNING run_id;

